import{_ as a,o,c as i,a7 as t}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Life Leaf Privacy Policy","description":"Official Privacy Policy for Life Leaf.","frontmatter":{"title":"Life Leaf Privacy Policy","description":"Official Privacy Policy for Life Leaf.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/life-leaf.md","filePath":"privacy/life-leaf.md"}'),r={name:"privacy/life-leaf.md"};function n(s,e,l,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-policy-for-life-leaf" tabindex="-1">Privacy Policy for Life Leaf <a class="header-anchor" href="#privacy-policy-for-life-leaf" aria-label="Permalink to &quot;Privacy Policy for Life Leaf&quot;">​</a></h1><p><strong>Effective Date:</strong> August 23, 2026<br><strong>Last Updated:</strong> August 23, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Life Leaf is a private, offline-first diary developed by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information stored on your device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information stored on your device&quot;">​</a></h2><p>Life Leaf can store diary titles and rich-text entries, entry dates and times, moods, tags, favourites, archived or trashed status, optional places and weather notes, attached photos or files, and app preferences. This information remains in app-local storage on your device unless you explicitly export or share it.</p><p>The developer does not receive your diary or app settings. Life Leaf does not automatically upload this information to a developer-operated server.</p><h2 id="optional-reminders-and-notifications" tabindex="-1">Optional reminders and notifications <a class="header-anchor" href="#optional-reminders-and-notifications" aria-label="Permalink to &quot;Optional reminders and notifications&quot;">​</a></h2><p>On Android, you can optionally enable local reminders for writing, prompts, memories from the same date in earlier years, or gentle diary statistics. Life Leaf requests notification permission only when you choose to enable a reminder. Reminder schedules are processed on the device, and notification wording does not include diary content.</p><p>Android controls delivery, timing, and lock-screen visibility. Disabling a reminder or notification permission stops the corresponding notifications.</p><h2 id="app-lock-biometrics-and-screenshots" tabindex="-1">App lock, biometrics, and screenshots <a class="header-anchor" href="#app-lock-biometrics-and-screenshots" aria-label="Permalink to &quot;App lock, biometrics, and screenshots&quot;">​</a></h2><p>If you set an app PIN, Life Leaf stores a salted PBKDF2-SHA-256 verifier rather than the PIN itself. Optional biometric unlock becomes available only after a PIN is set and uses Android&#39;s biometric and Keystore services. Life Leaf does not receive or store biometric templates.</p><p>Optional screenshot protection asks Android to block screenshots and screen recording where supported. These features supplement, but do not replace, a secure device lock and device encryption.</p><h2 id="backup-restore-sharing-and-external-files" tabindex="-1">Backup, restore, sharing, and external files <a class="header-anchor" href="#backup-restore-sharing-and-external-files" aria-label="Permalink to &quot;Backup, restore, sharing, and external files&quot;">​</a></h2><p>You can explicitly create a <code>.lifeleaf</code> backup. An optional encrypted backup uses AES-GCM with a key derived from the passphrase you provide. The passphrase is not stored by Life Leaf and cannot be recovered by the developer.</p><p>Life Leaf can receive text or an image that you deliberately share from another app. Shared content is opened as an unsaved draft for your review and is not added to the diary until you save it. Files exported, shared, or saved outside Life Leaf are handled by the destination you choose and remain there until you delete them.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information collected by the developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information collected by the developer&quot;">​</a></h2><p>Life Leaf has no account, advertising, analytics, tracking, or developer cloud. The developer does not receive diary entries, attachments, reminder schedules, PINs, biometric information, backup passphrases, or usage telemetry.</p><p>If you email support, the developer receives only the information you choose to include and uses it to respond. Do not email diary content, PINs, passphrases, or backup files.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the Android version and features you choose, Life Leaf may use:</p><ul><li>Notification permission for optional local reminders</li><li>Biometric authentication for optional app unlock after a PIN is set</li><li>File or document access for backups, restore, and attachments you select</li><li>Android&#39;s share target for text or an image you deliberately send to the app</li><li>Screenshot protection when you enable it</li></ul><p>Life Leaf does not require contacts, call logs, SMS, microphone, or continuous location access.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and deletion&quot;">​</a></h2><p>Diary entries and preferences remain on your device until you delete them, clear app storage, or uninstall the app. Archived entries remain available until restored or deleted. Items in Trash remain until you restore or permanently delete them according to the controls shown in the app.</p><p>Clearing app storage or uninstalling removes app-local information. It does not remove <code>.lifeleaf</code> backups or other files saved or shared outside the app; delete those copies separately. There is no developer-operated account or cloud database to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s privacy&quot;">​</a></h2><p>Life Leaf is not designed to collect children&#39;s personal information through a developer-operated service.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to this policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to this policy&quot;">​</a></h2><p>This policy may be updated when Life Leaf&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',32)])])}const u=a(r,[["render",n]]);export{f as __pageData,u as default};
